/**
 * Programmatic fixture generation for TinySqueeze tests and demos.
 * All fixtures are generated deterministically — no external assets.
 *
 * In the browser context, this provides synthetic test images by drawing on canvas.
 * The actual fixture files on disk (in `fixtures/`) are generated by `scripts/generate-fixtures.py`
 * and committed to the repo for the 5-minute demo.
 */

export interface FixtureSpec {
  id: string;
  name: string;
  w: number;
  h: number;
  type: 'image/jpeg' | 'image/png';
  draw: (ctx: CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D, w: number, h: number) => void;
}

const SEED = 0xC0FFEE;
let rngState = SEED;
function rng() {
  rngState = (rngState * 1664525 + 1013904223) >>> 0;
  return (rngState >>> 8) / 0xFFFFFF;
}

function grayNoise(ctx: CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D, w: number, h: number) {
  const img = ctx.getImageData(0, 0, w, h);
  for (let i = 0; i < img.data.length; i += 4) {
    const v = Math.floor(100 + 100 * Math.sin(i / 5000) * Math.cos(i / 4000) + 40 * rng());
    img.data[i] = img.data[i + 1] = img.data[i + 2] = Math.max(0, Math.min(255, v));
    img.data[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
}

function graphicBands(ctx: CanvasRenderingContext2D | OffscreenCanvasRenderingContext2D, w: number, h: number) {
  const third = w / 3;
  // Left: blue
  ctx.fillStyle = '#1e3a8a';
  ctx.fillRect(0, 0, third, h);
  // Center: purple
  ctx.fillStyle = '#7c3aed';
  ctx.fillRect(third, 0, third, h);
  // Right: pink, bottom half transparent
  ctx.fillStyle = '#db2777';
  ctx.fillRect(2 * third, 0, third, h / 2);
  ctx.fillStyle = 'rgba(219, 39, 119, 0.5)';
  ctx.fillRect(2 * third, h / 2, third, h / 2);
}

export function buildFixtures(): FixtureSpec[] {
  return [
    {
      id: 'photo',
      name: 'sample-photo.jpg',
      w: 800,
      h: 600,
      type: 'image/jpeg',
      draw: grayNoise,
    },
    {
      id: 'graphic',
      name: 'sample-graphic.png',
      w: 400,
      h: 300,
      type: 'image/png',
      draw: graphicBands,
    },
    {
      id: 'small',
      name: 'sample-small.jpg',
      w: 200,
      h: 150,
      type: 'image/jpeg',
      draw: grayNoise,
    },
  ];
}

/** Create a File object from a fixture spec (for programmatic testing). */
export async function createFixtureFile(spec: FixtureSpec): Promise<File> {
  const canvas = new OffscreenCanvas(spec.w, spec.h);
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('OffscreenCanvas not available');
  spec.draw(ctx, spec.w, spec.h);
  const blob = await canvas.convertToBlob({ type: spec.type, quality: 0.82 });
  return new File([blob], spec.name, { type: spec.type });
}

/** Create a corrupt PNG file (truncated). */
export async function createCorruptPngFile(): Promise<File> {
  // Minimal valid PNG: 1x1 transparent pixel
  const png = new Uint8Array([
    0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, // signature
    0x00, 0x00, 0x00, 0x0d, // IHDR length
    0x49, 0x48, 0x44, 0x52, // IHDR
    0x00, 0x00, 0x00, 0x01, // width 1
    0x00, 0x00, 0x00, 0x01, // height 1
    0x08, 0x06, 0x00, 0x00, 0x00, // bit depth 8, RGBA, compression 0, filter 0, interlace 0
    0x1f, 0x15, 0xc4, 0x89, // IHDR CRC
    0x00, 0x00, 0x00, 0x0c, // IDAT length
    0x49, 0x44, 0x41, 0x54, // IDAT
    0x78, 0x9c, 0x62, 0x60, 0x60, 0x60, 0x00, 0x00, 0x00, 0x02, 0x00, 0x01, // compressed 1x1 transparent
    0x04, 0xbe, 0x00, 0x8e, // IDAT CRC (wrong, will fail)
    0x00, 0x00, 0x00, 0x00, // IEND length
    0x49, 0x45, 0x4e, 0x44, // IEND
    0xae, 0x42, 0x60, 0x82, // IEND CRC
  ]);
  // Truncate it to make it corrupt
  const corrupt = png.slice(0, png.length - 10);
  return new File([corrupt], 'corrupt.png', { type: 'image/png' });
}

/** Create a non-image file. */
export function createTextFile(): File {
  return new File(['this is not an image file'], 'not-an-image.txt', { type: 'text/plain' });
}

/** Load fixtures from committed `fixtures/` folder (for 5-minute demo). */
export async function loadDemoFixtures(): Promise<File[]> {
  const base = '/products/tinysqueeze/fixtures/';
  const names = ['sample-photo.jpg', 'sample-graphic.png', 'sample-small.jpg'];
  const files: File[] = [];
  for (const name of names) {
    try {
      const res = await fetch(base + name);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const blob = await res.blob();
      files.push(new File([blob], name, { type: blob.type }));
    } catch {
      // Fallback: generate programmatically
      const spec = buildFixtures().find((s) => s.name === name);
      if (spec) files.push(await createFixtureFile(spec));
    }
  }
  return files;
}